package at.andrew.squashtap;
import android.app.*;import android.content.*;import android.graphics.Color;import android.view.*;import android.widget.*;import java.util.*;import java.util.concurrent.*;import org.json.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.android.controller.ActivityController;import org.robolectric.annotation.*;import org.robolectric.shadows.ShadowDialog;import org.robolectric.util.ReflectionHelpers;
import static org.junit.Assert.*;import static org.robolectric.Shadows.shadowOf;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,application=Application.class,qualifiers="w233dp-h233dp-round") @LooperMode(LooperMode.Mode.PAUSED) @GraphicsMode(GraphicsMode.Mode.LEGACY)
public class OpponentTransferUiTest {
 private ActivityController<MainActivity> controller;private MainActivity activity;private SharedPreferences preferences;private String martin;
 private static class PausedTasks extends AbstractExecutorService {final List<Runnable> queued=new ArrayList<>();boolean closed;public void execute(Runnable r){queued.add(r);}public void shutdown(){closed=true;}public List<Runnable> shutdownNow(){closed=true;return queued;}public boolean isShutdown(){return closed;}public boolean isTerminated(){return closed;}public boolean awaitTermination(long t,TimeUnit u){return closed;}}
 @Before public void launch(){MatchBook book=new MatchBook(new MatchState("active",3));book.add(0);book.add(1);book.importResult(new MatchResult("saved","2026-11-04",1,3,new int[][]{{11,4},{11,5}}));book.importResult(new MatchResult("older","2026-11-03",1,3,new int[][]{{11,4},{11,5}}));OpponentDirectory directory=new OpponentDirectory();martin=directory.add("Martin");directory.assign("saved",martin);
 preferences=RuntimeEnvironment.getApplication().getSharedPreferences("squash",0);preferences.edit().clear().putString("match_book",book.encode()).putString("opponent_book",directory.encode()).putString(MatchDisplayPolicy.ACTIVE_MATCH,"active").putBoolean("asked_match_notification",true).commit();controller=Robolectric.buildActivity(MainActivity.class).setup();activity=controller.get();activity.action(TouchTargets.MENU);}
 @After public void finish(){Dialog d=ShadowDialog.getLatestDialog();if(d!=null)d.dismiss();if(controller!=null)controller.pause().stop().destroy();}
 private View root(){return ShadowDialog.getLatestDialog().getWindow().getDecorView();}
 private List<View> all(View v){List<View> out=new ArrayList<>();out.add(v);if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)out.addAll(all(((ViewGroup)v).getChildAt(i)));return out;}
 private Button button(String text){for(View v:all(root()))if(v instanceof Button&&((Button)v).getText().toString().split("\n",2)[0].equals(text))return (Button)v;throw new AssertionError("Missing button "+text);}
 private void click(String text){button(text).performClick();}
 private EditText input(){for(View v:all(root()))if(v instanceof EditText)return (EditText)v;throw new AssertionError("Missing input");}
 private boolean contains(String text){for(View v:all(root()))if(v instanceof TextView&&((TextView)v).getText().toString().contains(text))return true;return false;}
 private MatchBook book(){return MatchBook.decode(preferences.getString("match_book",""));}
 private OpponentDirectory directory(){return OpponentDirectory.decode(preferences.getString("opponent_book",""));}
 private void red(Button b){int c=b.getBackgroundTintList().getDefaultColor();assertTrue(Color.red(c)>Color.blue(c));}
 private JSONObject payload(String csv)throws Exception{OpponentDirectory d=directory();JSONArray catalog=TransferClient.catalog(d);catalog.put(new JSONObject().put("id","new-person").put("name","Susi").put("archived",false));return new JSONObject().put("schema",1).put("sessionId","00112233445566778899aabbccddeeff").put("baseDirectory",TransferClient.base(book(),d)).put("currentMatchId","active").put("currentOpponentId","new-person").put("changeCurrentOpponent",true).put("opponents",catalog).put("csv",csv);}
 private TransferClient.Session preview(JSONObject payload)throws Exception{TransferClient.Session session=new TransferClient.Session();session.expiresAt=System.currentTimeMillis()+600000;ReflectionHelpers.setField(activity,"tasks",new PausedTasks());ReflectionHelpers.setField(activity,"transfer",session);ReflectionHelpers.callInstanceMethod(activity,"previewTransfer",ReflectionHelpers.ClassParameter.from(JSONObject.class,payload),ReflectionHelpers.ClassParameter.from(TransferClient.Session.class,session));return session;}
 @Test public void opponentManagerIsSeparateFromGreySettingsAndSupportsPhoneEntry(){click("Players");assertTrue(contains("Players"));assertNotNull(button("Edit names on phone"));assertNotNull(button("Add player"));assertNull(button("Back to Menu").getBackgroundTintList());}
 @Test public void addingAndChoosingNameKeepsScoreAndUndo(){String before=book().encode();click("Current match");click("Match options");click("Opponent: Opponent");click("Add player");input().setText("Susi");click("Save name");assertEquals("Susi",directory().nameFor("active"));assertEquals(before,book().encode());MatchBook restored=book();assertTrue(restored.undo());assertEquals(0,restored.current().game().red());}
 @Test public void savedNamePickerAssignsAndScoreboardAccessibilityUsesName(){click("Current match");click("Match options");click("Opponent: Opponent");click("Martin");assertEquals(martin,directory().opponentId("active"));click("Scoreboard");ScoreView view=ReflectionHelpers.getField(activity,"counter");assertTrue(view.getContentDescription().toString().contains("Martin"));}
 @Test public void renameUpdatesHistoricalResultsWithoutTouchingScore(){String before=book().encode();click("Players");click("Martin");click("Rename");input().setText("Mártin");click("Save name");assertEquals("Mártin",directory().nameFor("saved"));assertEquals(before,book().encode());}
 @Test public void deletingNameHasRedConfirmationAndKeepsHistory(){click("Players");click("Martin");red(button("Remove from player list"));click("Remove from player list");red(button("Remove name"));assertNull(button("Cancel").getBackgroundTintList());click("Remove name");assertTrue(directory().get(martin).archived);assertEquals("Martin",directory().nameFor("saved"));assertEquals(2,book().count());}
 @Test public void opponentAndCustomDateFiltersComposeThroughViews(){click("Results (2)");click("Filters");click("Opponent: All");click("Martin");click("Custom date range");List<EditText> inputs=new ArrayList<>();for(View v:all(root()))if(v instanceof EditText)inputs.add((EditText)v);inputs.get(0).setText("2026-11-04");inputs.get(1).setText("2026-11-04");click("Apply dates");assertTrue(contains("1 of 2 saved"));assertEquals(2,book().count());}
 @Test public void invalidDateRangeDoesNotMutateSavedData(){String before=book().encode();click("Results (2)");click("Filters");click("Custom date range");List<EditText> inputs=new ArrayList<>();for(View v:all(root()))if(v instanceof EditText)inputs.add((EditText)v);inputs.get(0).setText("2026-11-10");inputs.get(1).setText("2026-11-01");click("Apply dates");assertNotNull(inputs.get(0).getError());assertEquals(before,book().encode());}
 @Test public void speechActionOffersConfirmationBeforeSaving(){click("Players");click("Add player");click("Speak name");Intent started=shadowOf(activity).getNextStartedActivityForResult().intent;assertEquals(android.speech.RecognizerIntent.ACTION_RECOGNIZE_SPEECH,started.getAction());activity.onActivityResult(81,Activity.RESULT_OK,new Intent().putStringArrayListExtra(android.speech.RecognizerIntent.EXTRA_RESULTS,new ArrayList<>(Collections.singletonList("Susi"))));assertEquals("Susi",input().getText().toString());assertEquals(1,directory().list(false).size());click("Save name");assertEquals(2,directory().list(false).size());}
 @Test public void applyingPhonePreviewMergesResultsAndNamesAtomicallyAndPreservesActiveSession()throws Exception{String active=book().current().encode();MatchResult r=new MatchResult("foreign","2026-11-04",1,3,new int[][]{{11,5},{11,8}});JSONObject payload=payload(MatchCsv.export(Collections.singletonList(r),directory()));TransferClient.Session s=preview(payload);assertTrue(contains("1 new results"));click("Apply changes");assertEquals(3,book().count());assertEquals(active,book().current().encode());assertEquals("Susi",directory().nameFor("active"));assertEquals("active",preferences.getString(MatchDisplayPolicy.ACTIVE_MATCH,""));String stored=preferences.getAll().toString();assertFalse(stored.contains(s.key));assertFalse(stored.contains(s.owner));assertFalse(stored.contains(s.guest));}
 @Test public void cancellingPreviewAppliesNothing()throws Exception{String before=book().encode(),names=directory().encode();preview(payload(""));click("Cancel");assertEquals(before,book().encode());assertEquals(names,directory().encode());}
 @Test public void stalePhoneCatalogIsRejectedWithoutMutation()throws Exception{JSONObject p=payload("");p.put("baseDirectory","stale");String before=directory().encode();assertThrows(Exception.class,()->TransferClient.preview(p,book(),directory()));assertEquals(before,directory().encode());}
 @Test public void filteredExportCannotSilentlyReuseAnOlderOpenTransfer(){TransferClient.Session session=new TransferClient.Session();session.expiresAt=System.currentTimeMillis()+600000;ReflectionHelpers.setField(activity,"transfer",session);click("Results (2)");click("Options");click("Export CSV");click("Filtered results (2)");assertTrue(contains("Transfer already open"));assertTrue(contains("End the current transfer first"));assertEquals(session,ReflectionHelpers.getField(activity,"transfer"));}
}
